#!/usr/bin/env python3
"""Replace login page with client-side verify for both phone and email.
Run from your project root: python fix-login-final.py
"""

CONTENT = '"use client";\n\nimport { useState } from "react";\nimport { createClient } from "@/lib/supabase/client";\n\ntype Method = "email" | "phone";\n\nexport default function LoginPage() {\n  const [method, setMethod] = useState<Method>("phone");\n  const [email, setEmail] = useState("");\n  const [phone, setPhone] = useState("");\n  const [token, setToken] = useState("");\n  const [step, setStep] = useState<"input" | "code">("input");\n  const [error, setError] = useState<string | null>(null);\n  const [loading, setLoading] = useState(false);\n\n  function formatPhone(raw: string): string {\n    const digits = raw.replace(/\\\\D/g, "");\n    if (digits.startsWith("1") && digits.length === 11) return "+" + digits;\n    if (digits.length === 10) return "+1" + digits;\n    return "+" + digits;\n  }\n\n  async function handleSendCode(e: React.FormEvent) {\n    e.preventDefault();\n    setError(null);\n    setLoading(true);\n\n    const supabase = createClient();\n    let result;\n\n    if (method === "phone") {\n      const formatted = formatPhone(phone);\n      result = await supabase.auth.signInWithOtp({ phone: formatted });\n    } else {\n      result = await supabase.auth.signInWithOtp({\n        email,\n        options: { shouldCreateUser: true },\n      });\n    }\n\n    setLoading(false);\n\n    if (result.error) {\n      setError(result.error.message);\n      return;\n    }\n\n    setStep("code");\n  }\n\n  async function handleVerifyCode(e: React.FormEvent) {\n    e.preventDefault();\n    setError(null);\n    setLoading(true);\n\n    const supabase = createClient();\n    let result;\n\n    if (method === "phone") {\n      const formatted = formatPhone(phone);\n      result = await supabase.auth.verifyOtp({\n        phone: formatted,\n        token,\n        type: "sms",\n      });\n    } else {\n      result = await supabase.auth.verifyOtp({\n        email,\n        token,\n        type: "email",\n      });\n    }\n\n    if (result.error) {\n      setError(result.error.message);\n      setLoading(false);\n      return;\n    }\n\n    // createBrowserClient stores session in chunked cookies automatically.\n    // Small delay to ensure cookies are fully written before navigation.\n    await new Promise((r) => setTimeout(r, 500));\n    window.location.href = "/host/boards";\n  }\n\n  const displayIdentity = method === "phone" ? phone : email;\n\n  return (\n    <div className="min-h-screen flex items-center justify-center bg-gray-950 px-4">\n      <div className="w-full max-w-sm">\n        <h1 className="text-2xl font-bold text-white mb-1">Squares</h1>\n        <p className="text-gray-500 text-sm mb-8">\n          Sign in to create and manage boards.\n        </p>\n\n        {step === "code" ? (\n          <div>\n            <div className="rounded-lg border border-gray-800 bg-gray-900 p-6 mb-4">\n              <p className="text-white text-sm font-medium mb-1">\n                Enter your code\n              </p>\n              <p className="text-gray-500 text-sm">\n                We sent a 6-digit code to{" "}\n                <span className="text-gray-300">{displayIdentity}</span>\n              </p>\n            </div>\n\n            <form onSubmit={handleVerifyCode} className="space-y-4">\n              <div>\n                <label\n                  htmlFor="token"\n                  className="block text-sm text-gray-400 mb-1.5"\n                >\n                  Code\n                </label>\n                <input\n                  id="token"\n                  type="text"\n                  inputMode="numeric"\n                  autoComplete="one-time-code"\n                  required\n                  maxLength={6}\n                  value={token}\n                  onChange={(e) =>\n                    setToken(e.target.value.replace(/\\\\D/g, "").slice(0, 6))\n                  }\n                  placeholder="000000"\n                  className="w-full rounded-lg border border-gray-800 bg-gray-900 px-3 py-2.5 text-sm text-white placeholder-gray-600 outline-none focus:border-gray-600 transition-colors tracking-[0.3em] text-center font-mono"\n                />\n              </div>\n\n              {error && <p className="text-red-400 text-sm">{error}</p>}\n\n              <button\n                type="submit"\n                disabled={loading || token.length !== 6}\n                className="w-full rounded-lg bg-white text-gray-950 py-2.5 text-sm font-medium hover:bg-gray-200 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"\n              >\n                {loading ? "Verifying\\u2026" : "Verify"}\n              </button>\n            </form>\n\n            <button\n              onClick={() => {\n                setStep("input");\n                setToken("");\n                setError(null);\n              }}\n              className="mt-3 w-full text-center text-xs text-gray-600 hover:text-gray-400 transition-colors"\n            >\n              Start over\n            </button>\n          </div>\n        ) : (\n          <div>\n            <div className="flex rounded-lg border border-gray-800 bg-gray-900 mb-6 p-0.5">\n              <button\n                type="button"\n                onClick={() => { setMethod("phone"); setError(null); }}\n                className={`flex-1 text-sm py-2 rounded-md transition-colors ${\n                  method === "phone"\n                    ? "bg-gray-800 text-white font-medium"\n                    : "text-gray-500 hover:text-gray-300"\n                }`}\n              >\n                Phone\n              </button>\n              <button\n                type="button"\n                onClick={() => { setMethod("email"); setError(null); }}\n                className={`flex-1 text-sm py-2 rounded-md transition-colors ${\n                  method === "email"\n                    ? "bg-gray-800 text-white font-medium"\n                    : "text-gray-500 hover:text-gray-300"\n                }`}\n              >\n                Email\n              </button>\n            </div>\n\n            <form onSubmit={handleSendCode} className="space-y-4">\n              {method === "phone" ? (\n                <div>\n                  <label\n                    htmlFor="phone"\n                    className="block text-sm text-gray-400 mb-1.5"\n                  >\n                    Phone number\n                  </label>\n                  <input\n                    id="phone"\n                    type="tel"\n                    required\n                    value={phone}\n                    onChange={(e) => setPhone(e.target.value)}\n                    placeholder="(555) 123-4567"\n                    className="w-full rounded-lg border border-gray-800 bg-gray-900 px-3 py-2.5 text-sm text-white placeholder-gray-600 outline-none focus:border-gray-600 transition-colors"\n                  />\n                </div>\n              ) : (\n                <div>\n                  <label\n                    htmlFor="email"\n                    className="block text-sm text-gray-400 mb-1.5"\n                  >\n                    Email\n                  </label>\n                  <input\n                    id="email"\n                    type="email"\n                    required\n                    value={email}\n                    onChange={(e) => setEmail(e.target.value)}\n                    placeholder="you@example.com"\n                    className="w-full rounded-lg border border-gray-800 bg-gray-900 px-3 py-2.5 text-sm text-white placeholder-gray-600 outline-none focus:border-gray-600 transition-colors"\n                  />\n                </div>\n              )}\n\n              {error && <p className="text-red-400 text-sm">{error}</p>}\n\n              <button\n                type="submit"\n                disabled={loading}\n                className="w-full rounded-lg bg-white text-gray-950 py-2.5 text-sm font-medium hover:bg-gray-200 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"\n              >\n                {loading ? "Sending\\u2026" : "Send sign-in code"}\n              </button>\n            </form>\n          </div>\n        )}\n      </div>\n    </div>\n  );\n}\n'

with open("src/app/login/page.tsx", "w", encoding="utf-8") as f:
    f.write(CONTENT)
print("Done. Verify with: grep verifyOtp src/app/login/page.tsx")
